/**
 * Register P-1 (owner decision 2026-11-20): the compliance evidence report is generated by
 * POST /compliance/reports, so its HTML rendering is downloaded with a POST. The real client runs against a mocked
 * fetch: `download` with a body sends a POST with that JSON body and an Idempotency-Key; without one it stays the GET
 * every other caller uses.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import apiYaml from '../../../sangam-rest/api/sangam-api.yaml?raw';
import { download } from './client';

type Call = { url: string; method: string; headers: Headers; body: unknown };
let calls: Call[] = [];
let saved: { name: string; href: string }[] = [];

beforeEach(() => {
  calls = [];
  saved = [];
  vi.stubGlobal(
    'fetch',
    vi.fn(async (url: string, init: RequestInit) => {
      calls.push({ url, method: init.method ?? 'GET', headers: new Headers(init.headers), body: init.body });
      return new Response('<html><body>report</body></html>', { status: 200, headers: { 'Content-Type': 'text/html' } });
    }),
  );
  URL.createObjectURL = vi.fn(() => 'blob:report');
  URL.revokeObjectURL = vi.fn();
  vi.spyOn(HTMLAnchorElement.prototype, 'click').mockImplementation(function (this: HTMLAnchorElement) {
    saved.push({ name: this.download, href: this.href });
  });
});
afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

const PERIOD = { from: '2026-10-31T18:30:00.000Z', to: '2026-11-30T18:30:00.000Z', verifyChains: true, format: 'html' };

describe('P-1: download by POST', () => {
  it('the contract has POST /compliance/reports and no GET of it', () => {
    const block = /^ {2}\/compliance\/reports:\n((?: {4}.*\n)+)/m.exec(apiYaml.replace(/\r\n/g, '\n'));
    expect(block).not.toBeNull();
    expect([...block![1].matchAll(/^ {4}([a-z]+):$/gm)].map((m) => m[1])).toEqual(['post']);
  });

  it('with a body it sends a POST: JSON body, Idempotency-Key, nothing of the body in the URL', async () => {
    await download('/compliance/reports', undefined, 'compliance-report.html', PERIOD);
    expect(calls).toHaveLength(1);
    const c = calls[0];
    expect(c.method).toBe('POST');
    expect(new URL(c.url, 'http://x').pathname).toBe('/api/v1/compliance/reports');
    expect(new URL(c.url, 'http://x').search).toBe('');
    expect(JSON.parse(String(c.body))).toEqual(PERIOD);
    expect(c.headers.get('Content-Type')).toBe('application/json');
    expect(c.headers.get('Idempotency-Key')).toBeTruthy();
    expect(c.headers.get('Accept')).toBe('*/*');
    expect(saved.map((s) => s.name)).toEqual(['compliance-report.html']);
  });

  it('without a body it stays a GET with the query, no body and no Idempotency-Key', async () => {
    await download('/audit/evidence-pack', { businessKey: 'BK-1' }, 'evidence-BK-1.zip');
    expect(calls).toHaveLength(1);
    const c = calls[0];
    expect(c.method).toBe('GET');
    expect(new URL(c.url, 'http://x').search).toBe('?businessKey=BK-1');
    expect(c.body).toBeUndefined();
    expect(c.headers.get('Idempotency-Key')).toBeNull();
    expect(c.headers.get('Content-Type')).toBeNull();
    expect(saved.map((s) => s.name)).toEqual(['evidence-BK-1.zip']);
  });
});
